func (r *Runtime) Health(ctx context.Context) apphost.HealthReport {
	return r.healthCache.Get(ctx, r.health)
}

func (r *Runtime) Handler() http.Handler { return r.HTTPHandler }

func (r *Runtime) Run(ctx context.Context) error {
	for _, start := range r.start {
		if err := start(ctx); err != nil {
			return err
		}
	}
	return nil
}

func (r *Runtime) Close(ctx context.Context) error {
	var errs []error
	for i := len(r.stop) - 1; i >= 0; i-- {
		if err := r.stop[i](ctx); err != nil {
			errs = append(errs, err)
		}
	}
	return errors.Join(errs...)
}
